 "guidance": [
  {
   "metric": "margin",
   "statement": "Maintain the EBITDA margin band of 18% to 20% for the full year.",
   "quote": "we believe as we go forward, for the year we should be able to maintain the band of what we have spoken of 18% to 20%.",
   "page": 27,
   "horizon": "FY27",
   "quantitative": true
  },
  {
   "metric": "volume",
   "statement": "Expect volume growth of about 8% to 9% going forward.",
   "quote": "we feel that it would be reasonable to expect to see a volume growth of about 8% to 9% going forward.",
   "page": 28,
   "horizon": "remaining year",
   "quantitative": true
  },
  {
   "metric": "margin",
   "statement": "Gross margin is expected to be in the band of 41% to 43%.",
   "quote": "This band of about 41% to 43% would really be the band we should be looking forward to.",
   "page": 26,
   "horizon": "second half",
   "quantitative": true
  },
  {
   "metric": "margin",
   "statement": "VAE facility to give 300 bps to 500 bps advantage on relevant products.",
   "quote": "we believe that when it really works to its full potential, it should really give us some advantage of 300 bps to 500 bps on relevant products.",
   "page": 27,
   "horizon": "medium term",
   "quantitative": true
  },
  {
   "metric": "capex",
   "statement": "Total VAE CapEx is about Rs. 3,250 crores.",
